// Timestamps de medicion (benchmark Escenario B)
let ts_start = Date.now();
let cycle_id = "schedule";
try {
  const wb = $("Medir Ciclo").first().json.body;
  if (wb) {
    ts_start = wb.ts_start || ts_start;
    cycle_id = wb.cycle_id || cycle_id;
  }
} catch (e) {}

//Script para Internacion
const ordenesLimpias = $input.all().map((item) => {
  const data = item.json;

  // desestructuracion de datos para mejor orden
  const paciente = data.patient_data || {};
  const orden = data.clinical_order || {};

  const nombre = paciente.first_name || "";
  const apellido = paciente.last_name || "";

  // pseudonimo de telegram
  const iniciales = `${nombre.charAt(0) || "X"}.${apellido.charAt(0) || "X"}.`;

  // formateo fecha nacimiento
  const bd = paciente.birth_date || {};
  const fechaNac = bd.year ? `${bd.year}-${bd.month.toString().padStart(2, '0')}-${bd.day.toString().padStart(2, '0')}` : "1900-01-01";

  // urgencia como booleano
  const prioridad = !!data.is_urgent;

  // ubicacion
  const ubicacion = `${orden.sector || "S/D"} - Hab: ${orden.room || "-"} Cama: ${orden.bed || "-"}`;

  let mod = orden.modality || "DX";
  if (mod === "CR") mod = "DX";

  let setting = orden.study_setting || "En Efector";
  if (setting.toLowerCase() === "en cama") setting = "En Cama";
  else setting = "En Efector";

  return {
    external_id: `I-${data.request_id}`,
    source_system: "INTERNACION",
    modality: mod,
    description: orden.procedure || "Estudio",
    origin_service: "Internacion",
    diagnosis: orden.diagnosis || "Sin diagnostico",
    observations: orden.observations || "Sin observaciones",
    order_date: new Date(`${orden.date}-03:00`).toISOString(),
    patient_location: ubicacion,
    study_setting: setting,
    patient_name: nombre,
    patient_lastname: apellido,
    patient_pseudonym: iniciales,
    patient_dni: String(paciente.national_id || "0"),
    patient_dob: fechaNac,
    patient_sex: paciente.sex === "F" ? "FEMALE" : (paciente.sex === "M" ? "MALE" : "OTHER"),
    requesting_physician: orden.requesting_physician || "No especificado",
    is_urgent: prioridad,
    is_active: true,
    ts_start,
    cycle_id,
  };
});

return ordenesLimpias.map((orden) => ({ json: orden }));

