// Script para Guardia
const ordenesLimpias = $input.all().map((item) => {
  const data = item.json;

  const partesNombre = (data.nom_paciente || "").split(", ");
  const apellido = partesNombre[0] || "";
  const nombre = partesNombre[1] || "";
  const iniciales = `${nombre.charAt(0) || "X"}.${apellido.charAt(0) || "X"}.`;

  const prioridad = data.urgente === "SI";
  const prestacion = data.estudio_req || "Sin detalle";

  let modalidadInferida = "DX";
  if (prestacion.toLowerCase().includes("resonancia") || prestacion.toLowerCase().includes("rm")) modalidadInferida = "MR";
  else if (prestacion.toLowerCase().includes("ecograf") || prestacion.toLowerCase().includes("ecografía")) modalidadInferida = "US";
  else if (prestacion.toLowerCase().includes("tomograf") || prestacion.toLowerCase().includes("tc") || prestacion.toLowerCase().includes("tac")) modalidadInferida = "CT";
  else if (prestacion.toLowerCase().includes("radiograf") || prestacion.toLowerCase().includes("rx")) modalidadInferida = "DX";

  let setting = data.lugar_estudio || "En Efector";
  if (setting.toLowerCase().includes("cama")) setting = "En Cama";
  else setting = "En Efector";

  return {
    external_id: `G-${data.id_transaccion}`,
    source_system: "GUARDIA",
    modality: modalidadInferida,
    description: prestacion,
    diagnosis: data.diagnostico || "Sin diagnostico",
    observations: data.observaciones || "Sin observaciones",
    patient_location: data.ubicacion_actual || "Guardia",
    origin_service: "Guardia",
    order_date: new Date(`${data.fecha_hora}-03:00`).toISOString(),
    study_setting: setting, 
    patient_name: nombre,
    patient_lastname: apellido,
    patient_pseudonym: iniciales,
    patient_dni: String(data.doc_identidad || "0"),
    patient_dob: data.fecha_nacimiento || "1900-01-01",
    patient_sex: data.sexo === "F" ? "FEMALE" : (data.sexo === "M" ? "MALE" : "OTHER"),
    requesting_physician: data.solicitante || "Solicitante no especificado",
    is_urgent: prioridad,
    is_active: true,
    ts_start,
    cycle_id,
  };
});

return ordenesLimpias.map((orden) => ({ json: orden }));

